// validator will reject the binary — which is correct behavior.
//
// Modules:
//   compiler-parser.js   — Stage 1: tokenize, parseSexpr, ParseError
//   compiler-stages.js   — Stages 2-4: resolveIncludes, expandMacros, checkTypes
